using System.Reflection;
using NetArchTest.Rules;
using PaymentAuthorization.Application;
using PaymentAuthorization.Domain;
using PaymentAuthorization.Infrastructure;

namespace PaymentAuthorization.ArchitectureTest;

public sealed class LayerDependencyTests
{
    private const string DomainNs = "PaymentAuthorization.Domain";
    private const string ApplicationNs = "PaymentAuthorization.Application";
    private const string InfrastructureNs = "PaymentAuthorization.Infrastructure";

    private static readonly string[] TechnicalNamespaces =
    [
        "System.Net", "System.IO", "System.Data", "System.Text.Json", "System.Diagnostics.Process",
        "Microsoft.Extensions", "Microsoft.EntityFrameworkCore", "Newtonsoft",
    ];

    private static readonly Assembly Domain = typeof(Money).Assembly;
    private static readonly Assembly Application = typeof(AuthorizePayment).Assembly;
    private static readonly Assembly Infrastructure = typeof(FileSystemReceiptStore).Assembly;

    [Fact]
    public void Domain_does_not_depend_on_outer_layers()
        => AssertNoViolations(Types.InAssembly(Domain).ShouldNot()
            .HaveDependencyOnAny(ApplicationNs, InfrastructureNs));

    [Fact]
    public void Domain_does_not_depend_on_technical_details()
        => AssertNoViolations(Types.InAssembly(Domain).ShouldNot().HaveDependencyOnAny(TechnicalNamespaces));

    [Fact]
    public void Application_does_not_depend_on_infrastructure()
        => AssertNoViolations(Types.InAssembly(Application).ShouldNot().HaveDependencyOn(InfrastructureNs));

    [Fact]
    public void Application_does_not_depend_on_technical_details()
        => AssertNoViolations(Types.InAssembly(Application).ShouldNot().HaveDependencyOnAny(TechnicalNamespaces));

    [Fact]
    public void Assemblies_only_reference_inward()
    {
        Assert.DoesNotContain(Domain.GetReferencedAssemblies(), a => a.Name!.StartsWith("PaymentAuthorization."));
        Assert.DoesNotContain(Application.GetReferencedAssemblies(),
            a => a.Name == Infrastructure.GetName().Name);
    }

    private static void AssertNoViolations(ConditionList rule)
    {
        var result = rule.GetResult();
        Assert.True(result.IsSuccessful,
            "Layer violation in: " + string.Join(", ", result.FailingTypeNames ?? []));
    }
}
E
